// === Tab: Tetris ===
class Tetris {
	constructor(pos, dim, s, pal) {
		this.pos = pos;
		this.w = dim.x;
		this.h = dim.y;
		this.s = s;
		this.pal = pal;
		this.tiles = [];
		this.initGrid(); // this.grid = [];
	}

	initGrid() {
		this.grid = [];
		for (let y = 0; y < field.y; y++) {
			this.grid[y] = [];
			for (let x = 0; x < field.x; x++) {
				this.grid[y][x] = false;
			}
		}
	}

	genGrid() {
		this.initGrid();
		for (let tile of this.tiles) {
			const pos = tile.pos;
			const shape = tile.shape;
			for (let j = 0; j < shape.length; j++) {				
				for (let i = 0; i < shape[j].length; i++) {
					if (int(shape[j][i])>0) this.grid[j+pos.y][i+pos.x] = tile.clr;
				}
			}
		}
	}

	addTile(shape, pos, clr) {
		// check already occupied
		this.genGrid();
		for (let j = 0; j < shape.length; j++) {				
			for (let i = 0; i < shape[j].length; i++) {
				if (int(shape[j][i])>0 && this.grid[j+pos.y][i+pos.x]) return false;
			}
		}

		this.tiles.push({shape, pos, clr});
	}

	draw() {
		push()
		translate(this.pos.x, this.pos.y);

		// borders
		const th = 4;
		for (let y = 0; y < this.h; y++) {
			const n1 = noise(1, y, frameCount / 43) * 2 * this.s;
			const n2 = noise(111, y, frameCount / 34) * 2 * this.s;
			noStroke();
			// left side
			for (let i = 0; i < n1; i+=th) {
				for (let j = 0; j < this.s; j+=5) {					
					const nc = noise(1, i*y+j, frameCount / 43);
					fill(this.pal[~~(nc*this.pal.length)]);
					rect(-i, y*this.s+j, -th+1, 3);
				}
			}
			// right side
			for (let i = 0; i < n2; i+=th) {
				for (let j = 0; j < this.s; j+=5) {
					var nc = noise(111, i*y+j, frameCount / 34);
					fill(this.pal[~~(nc*this.pal.length)]);
					rect(this.w * this.s + i, y*this.s+j, th-1, 3); // this.s-2
				}
			}
		}

		// tiles
		strokeWeight(~~max(2, S/10));
		stroke("#00303b");
		noFill();
		rect(0, 0, this.w * this.s, this.h * this.s);
		this.genGrid();
		for (let j = 0; j < field.y; j++) {		
			for (let i = 0; i < field.x; i++) {
				const val = this.grid[j][i];
				if (val) {
					fill(val);
					rect(i * S, j * S, S)
				}
			}
		}
		pop()
	}
}

