const field = {x: 10, y: 18};
const palette = ["#f1f2da", "#ffce96", "#ff7777", "#00303b"]; // palette from https://lospec.com/palette-list/ayy4
let tetris, intPart, bg;
let pxlFnt;

function preload() {
  // https://developers.google.com/fonts/docs/getting_started?hl=de&apix_params=%7B%22family%22%3A%5B%22Micro%205%22%5D%7D
  pxlFnt = loadFont("https://fonts.gstatic.com/s/micro5/v1/H4cnBX2MkcfEngTr0gYQ7LO5mqc.ttf");
}

function setup() {
	S = ~~(min(windowWidth/(field.x+4), windowHeight/(field.y+2))/10)*10;
	createCanvas(S * (field.x+4), S * (field.y+2));
	describe("tetris field with some tiles from same integer partition (length ^^)");
	frameRate(30);
	textFont(pxlFnt);
	textSize(S);
	textAlign(CENTER, BOTTOM);

	var pos = {x: width/2-field.x/2*S, y: S};
	tetris = new Tetris(pos, field, S, palette);

	intPart = ~~random(integer_partitions.length);
	for (let i = 0; i < 10; i++) {		
		const tile = random(integer_partitions[intPart]);
		addTile(tile);
	}

	loop();
}

function draw() {
	background(palette[0]);
	noStroke();
	fill(palette[3]);
	text("Integer Partition: " + (2+intPart), width/2, S)
	tetris.draw();
	// noLoop() removed for animation
}

function addTile(tile) {
	let w = 0, h = tile.length;
	for (let i = 0; i < tile.length; i++) {
		if (tile[i].length > w) w = tile[i].length;
	}
	var pos = {x: ~~random(tetris.w-w), y: ~~random(tetris.h-h)};
	const col = random(palette);
	tetris.addTile(tile, pos, col)
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}
